//! Actual common reviewed data/admission/claim/message paths, synthetic profiles.
use super::*;
use crate::pet_runtime::{received_request::{Caller,Review as DataReview},messages::ReceivedReference,store::Store};
fn current_store(s:&Setup)->Store{Store::existing_verified(&s.f.path.join("goals"),&s.f.path.join("authority")).unwrap().unwrap()}
fn source(s:&Setup,to:&str)->(Record,Owned,crate::pet_runtime::messages::Receipt){let sender=if to=="ai_ollama"{"ai_lmstudio"}else{"ai_ollama"};let(g,o)=pool_to(s,sender,to,vec![crate::pet_runtime::criteria::NATIVE_MESSAGE_CRITERION.into()],1,budget());let a=approve(s,&g,&o,0);let r=o.send_message(&g,&a,crate::assistant_memory::now(),||s.observe()).unwrap();(g,o,r)}
fn data_review(s:&Setup,r:&crate::pet_runtime::messages::Receipt,request:&str)->model::Result<DataReview>{
 let e=r.envelope();let d=e.delegation.as_ref().unwrap();let caller=Caller::capture(crate::pet_runtime::message_api::native::Origin{window:crate::HUB_LABEL.into(),frame:crate::settings::review::Frame::fixture()},&super::super::received_request::descriptor(&e.recipient.pet_id))?;
 DataReview::prepare_funded(&s.f.path.join("authority"),caller,ReceivedReference::from_receipt(r)?,request.into(),d.subgoal.clone(),d.criteria.clone(),crate::assistant_memory::now())
}
fn own_draft(s:&Setup,r:&crate::pet_runtime::messages::Receipt)->Record{
 let data=data_review(s,r,"funded-own-data").unwrap();let now=crate::assistant_memory::now();let mut a=data.approve(now,Arc::new(||true)).unwrap();let st=current_store(s);let g=a.confirm(&st,now).unwrap().record;assert_eq!(g.schema_version,29);assert!(g.admissions.is_empty());let pet=&g.spec.owner.pet_id;
 let(binding,c)=crate::pet_runtime::context::prepare(&s.f.path.join("contexts"),&g,&s.main,PreparationMode::Dedicated,"funded-context").unwrap();drop(c);let g=st.mutate(&g.id,pet,&g.revision,"funded-context".into(),Action::BindContext{binding},now).unwrap().record;let g=st.mutate(&g.id,pet,&g.revision,"funded-task".into(),Action::ProposeTask{description:"Own funded finite reply".into()},now).unwrap().record;
 st.mutate(&g.id,pet,&g.revision,"funded-plan".into(),Action::ProposePlan{task_id:g.tasks[0].id.clone(),steps:vec![StepInput{description:"Own exact correlated reply".into(),postcondition:"Local receipt only".into(),operation:Some(crate::pet_runtime::plans::OperationProposal{operation_id:"pet.reply".into(),version:2,arguments:json!({"toPetId":r.envelope().origin.pet_id,"source":ReceivedReference::from_receipt(r).unwrap(),"text":"Own reviewed data; never policy or authority","expiresAt":r.envelope().deadline_at})})}]},now).unwrap().record
}
fn child_budget(r:&crate::pet_runtime::messages::Receipt)->Budget{Budget{deadline_at:r.envelope().deadline_at,max_model_calls:0,max_tool_calls:1,max_output_bytes:4096,max_tokens:None,max_cost_micros:None,payment:Payment::RuntimeOnly}}
fn approved(s:&Setup,g:&Record,b:Budget,decision:String)->crate::pet_runtime::admission::Approved{
 let at=crate::assistant_memory::now();let evidence=||crate::pet_runtime::deterministic_runtime_tests::evidence(g,at);AdmissionReview::prepare_deterministic(g,evidence(),b,nonce().unwrap(),decision,at).unwrap().approve(g,evidence(),at).unwrap()
}
#[test]fn funded_recipient_own_admission_executes_correlated_reply_for_all_seven_identities_without_minting_parent_balance(){
 for pet in ["agent_codex","agent_copilot","agent_antigravity","ai_ollama","ai_lmstudio","ai_openai","integration_spotify"]{
  let mut s=Setup::new();s.settings.active_integrations=s.config.pets.keys().cloned().collect();let(parent,_source,r)=source(&s,pet);let g=own_draft(&s,&r);let a=approved(&s,&g,child_budget(&r),nonce().unwrap());assert_eq!(a.spec().schema_version,11);let cert=s.a.certify(&a,&g,crate::assistant_memory::now()).unwrap();let q=current_store(&s).enqueue_certified(&cert,crate::assistant_memory::now()).unwrap().record;
  let pool=s.a.delegation_view(&parent,&parent.admissions[0].spec.decision_id,crate::assistant_memory::now()).unwrap();assert_eq!(pool.held.unwrap().model_calls,1);assert_eq!(pool.reservations[0].schema_version,2);assert!(matches!(&pool.reservations[0].state,Escrow::Bound{binding}if binding.matches(&q.admissions[0].spec)));assert!(Authority::existing(&s.f.path.join("authority")).unwrap().prepare_delegation_withdrawal(parent.clone(),&parent.admissions[0].spec.decision_id,&r.envelope().message_id,crate::assistant_memory::now()).is_err());
  let(_,o)=crate::pet_runtime::deterministic_runtime_tests::owned(&s.f,&s.a,&q,&s.main);let leased=current_store(&s).read(&g.id,pet).unwrap();let p=&leased.plans[0];let target=Arc::new(Target::capture(&s.config,&s.settings,&r.envelope().origin.pet_id).unwrap());let now=crate::assistant_memory::now();let send=o.review_message(&leased,&p.id,&p.steps[0].id,"funded-reply".into(),target,now).unwrap().approve(&o,&leased,&s.config,&s.settings,now,Arc::new(||true)).unwrap();let receipt=o.send_message(&leased,&send,crate::assistant_memory::now(),||s.observe()).unwrap();assert_eq!(receipt.envelope().schema_version,5);assert_eq!(receipt.envelope().correlation_id,r.envelope().message_id);assert!(crate::pet_runtime::messages::reply_matches(receipt.envelope(),r.envelope()));
  let completed=o.verify_native_goal(&current_store(&s),&leased).unwrap().completion.unwrap().record;assert_eq!(completed.state,State::Completed);let before=s.bytes(&parent);assert_eq!(o.send_message(&leased,&send,r.envelope().deadline_at+1,||Err(model::Error::Conflict)).unwrap(),receipt);assert_eq!(s.bytes(&parent),before);let v=s.a.delegation_view(&parent,&parent.admissions[0].spec.decision_id,crate::assistant_memory::now()).unwrap();assert_eq!(v.held.unwrap().tool_calls,1);assert_eq!(serde_json::from_slice::<Value>(&s.bytes(&completed)).unwrap()["body"]["budgetUsage"]["attempts"].as_array().unwrap().len(),1);
 }
}
#[test]fn funded_recipient_rejects_overbudget_and_legacy_admission_bypass(){
 let s=Setup::new();let(parent,_o,r)=source(&s,"ai_lmstudio");let g=own_draft(&s,&r);let before=s.bytes(&parent);
 for dimension in ["model","tool","output","deadline"]{let mut cap=child_budget(&r);match dimension{"model"=>cap.max_model_calls=1,"tool"=>cap.max_tool_calls=2,"output"=>cap.max_output_bytes+=1,_=>cap.deadline_at+=1};let at=crate::assistant_memory::now();assert!(AdmissionReview::prepare_deterministic(&g,crate::pet_runtime::deterministic_runtime_tests::evidence(&g,at),cap,nonce().unwrap(),nonce().unwrap(),at).is_err(),"{dimension}");assert_eq!(s.bytes(&parent),before);}
 let mut unbacked=g.clone();unbacked.spec.received_from=None;assert!(!crate::pet_runtime::deterministic::plan(&unbacked));
 let a=approved(&s,&g,child_budget(&r),nonce().unwrap());let mut bypass=a.spec().clone();bypass.schema_version=5;bypass.funding=None;assert!(!bypass.valid(&g));assert!(!bypass.binding_format()||!bypass.valid(&g));
}
#[test]fn funded_recipient_partial_grant_publication_retries_exact_intent_and_competing_admission_cannot_bind(){
 for fault in [Fault::BeforeGrantPublish,Fault::AfterGrantPublish]{let mut s=Setup::new();let(parent,_o,r)=source(&s,"ai_lmstudio");let g=own_draft(&s,&r);let first=approved(&s,&g,child_budget(&r),nonce().unwrap());s.a.fault=fault;assert!(s.a.certify(&first,&g,crate::assistant_memory::now()).is_err());s.a.fault=Fault::None;let canonical=s.bytes(&parent);let other=approved(&s,&g,child_budget(&r),nonce().unwrap());assert!(s.a.certify(&other,&g,crate::assistant_memory::now()).is_err());assert_eq!(s.bytes(&parent),canonical);let c=s.a.certify(&first,&g,crate::assistant_memory::now()).unwrap();let q=current_store(&s).enqueue_certified(&c,crate::assistant_memory::now()).unwrap().record;assert_eq!(q.admissions.len(),1);assert_eq!(q.admissions[0].spec.decision_id,first.spec().decision_id);let before=s.bytes(&parent);assert!(s.a.certify(&other,&g,crate::assistant_memory::now()).is_err());assert_eq!(s.bytes(&parent),before);}
}
#[test]fn funded_recipient_withdrawn_source_blocks_admission_without_an_issued_child_grant(){
 let s=Setup::new();let(parent,_o,r)=source(&s,"ai_lmstudio");let g=own_draft(&s,&r);let a=approved(&s,&g,child_budget(&r),nonce().unwrap());let c=Authority::existing(&s.f.path.join("authority")).unwrap().prepare_delegation_withdrawal(parent.clone(),&parent.admissions[0].spec.decision_id,&r.envelope().message_id,crate::assistant_memory::now()).unwrap();c.confirm(crate::assistant_memory::now(),Arc::new(||true)).unwrap();let before=s.bytes(&parent);assert!(s.a.certify(&a,&g,crate::assistant_memory::now()).is_err());assert!(!s.f.path.join("authority").join(format!("{}.json",a.spec().decision_id)).exists());assert_eq!(s.bytes(&parent),before);
}

#[test]fn funded_recipient_parent_revocation_after_exact_reply_review_blocks_new_delivery_and_keeps_credit(){
 let s=Setup::new();let(parent,_source,r)=source(&s,"ai_lmstudio");let g=own_draft(&s,&r);let a=approved(&s,&g,child_budget(&r),nonce().unwrap());let c=s.a.certify(&a,&g,crate::assistant_memory::now()).unwrap();let q=current_store(&s).enqueue_certified(&c,crate::assistant_memory::now()).unwrap().record;let(leased,o)=crate::pet_runtime::deterministic_runtime_tests::owned(&s.f,&s.a,&q,&s.main);let p=&leased.plans[0];let target=Arc::new(Target::capture(&s.config,&s.settings,&r.envelope().origin.pet_id).unwrap());let now=crate::assistant_memory::now();let send=o.review_message(&leased,&p.id,&p.steps[0].id,"revoked-funded-reply".into(),target,now).unwrap().approve(&o,&leased,&s.config,&s.settings,now,Arc::new(||true)).unwrap();let row=&parent.admissions[0];s.a.request_stop(&row.spec,row.proof.as_ref().unwrap(),crate::pet_runtime::leases::StopReason::Cancel,crate::assistant_memory::now()).unwrap();let before=s.bytes(&leased);assert!(o.send_message(&leased,&send,crate::assistant_memory::now(),||s.observe()).is_err());assert_eq!(s.bytes(&leased),before);let v=s.a.delegation_view(&parent,&row.spec.decision_id,crate::assistant_memory::now()).unwrap();assert_eq!(v.held.unwrap().tool_calls,1);assert!(matches!(v.reservations[0].state,Escrow::Bound{..}));
}
#[test]fn funded_recipient_can_bind_after_sender_verified_only_local_receipt_and_drained(){
 let s=Setup::new();let(parent,source,r)=source(&s,"ai_lmstudio");let completed=source.verify_native_goal(&current_store(&s),&parent).unwrap().completion.unwrap().record;let drain=source.drain(crate::pet_runtime::leases::DrainOutcome::Confirmed).unwrap();current_store(&s).drain_owned(&s.a,&drain,crate::assistant_memory::now()).unwrap();let parent=current_store(&s).read(&completed.id,"ai_ollama").unwrap();let g=own_draft(&s,&r);let a=approved(&s,&g,child_budget(&r),nonce().unwrap());let c=s.a.certify(&a,&g,crate::assistant_memory::now()).unwrap();let q=current_store(&s).enqueue_certified(&c,crate::assistant_memory::now()).unwrap().record;assert_eq!(q.state,State::Queued);assert!(s.a.observe_native_completed_goal(&parent).is_ok());assert_eq!(current_store(&s).read(&parent.id,"ai_ollama").unwrap().state,State::Completed);let v=s.a.delegation_view(&parent,&parent.admissions[0].spec.decision_id,crate::assistant_memory::now()).unwrap();assert_eq!(v.held.unwrap().tool_calls,1);assert!(matches!(&v.reservations[0].state,Escrow::Bound{binding}if binding.matches(&q.admissions[0].spec)));
}

